-- Keep the legacy audit_log table untouched. Also cover environments that applied the old 0032/0033.
-- SQLite / Cloudflare D1 migration. IDs are generated by application code with crypto.randomUUID().
CREATE TABLE IF NOT EXISTS ops_ci_audit_log (
  id TEXT PRIMARY KEY NOT NULL,
  repo TEXT NOT NULL,
  sha TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('pending','success','failure','cancelled','blocked','approved','deployed')),
  trigger TEXT NOT NULL,
  actor TEXT,
  branch TEXT,
  environment TEXT CHECK(environment IS NULL OR environment IN ('staging','production','development')),
  duration_ms INTEGER CHECK(duration_ms IS NULL OR duration_ms >= 0),
  ts TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE
);
CREATE INDEX IF NOT EXISTS idx_ops_ci_audit_repo_ts ON ops_ci_audit_log(repo, ts DESC);
CREATE INDEX IF NOT EXISTS idx_ops_ci_audit_sha ON ops_ci_audit_log(sha);

-- Existing repo/time composite index already supports repository filtering.
-- The existing SHA index supports commit lookup. Use the actual ISO time column.
CREATE INDEX IF NOT EXISTS idx_ops_ci_audit_ts ON ops_ci_audit_log(ts DESC);
